mapper.select:
SELECT EXISTS (
    SELECT 1 FROM quote q
    WHERE q.id = #{quoteId,typeHandler=com.platform.reservation.UuidTypeHandler}
      AND q.move_request_id = #{requestId,typeHandler=com.platform.reservation.UuidTypeHandler}
      AND q.status = 'ACCEPTED'
      AND q.version_no = (
          SELECT max(latest.version_no)
          FROM quote latest
          WHERE latest.move_request_id = q.move_request_id
      )
)

SELECT NOT EXISTS (
    SELECT 1 FROM reservation r
    WHERE r.move_request_id = #{requestId,typeHandler=com.platform.reservation.UuidTypeHandler}
      AND r.status IN ('PENDING', 'CONFIRMED', 'RESCHEDULE_REQUESTED')
      AND r.scheduled_start_at < #{endAt}
      AND r.scheduled_end_at > #{startAt}

          AND r.id <> #{excludeId,typeHandler=com.platform.reservation.UuidTypeHandler}

)

SELECT r.id, r.idempotency_request_hash
FROM reservation r
WHERE r.idempotency_key = #{idempotencyKey}

SELECT count(*)
FROM reservation r
JOIN move_request mr ON mr.id = r.move_request_id
WHERE mr.customer_id = #{customerId,typeHandler=com.platform.reservation.UuidTypeHandler}

    AND r.move_request_id = #{requestId,typeHandler=com.platform.reservation.UuidTypeHandler}

