SELECT r.move_request_id, r.status, r.scheduled_start_at, r.scheduled_end_at, mr.customer_id
FROM reservation r
JOIN move_request mr ON mr.id = r.move_request_id
WHERE r.id = #{reservationId,typeHandler=com.platform.reservation.UuidTypeHandler}

    AND mr.customer_id = #{customerId,typeHandler=com.platform.reservation.UuidTypeHandler}

FOR UPDATE OF mr, r

SELECT r.move_request_id, r.status, r.scheduled_start_at, r.scheduled_end_at, mr.customer_id
FROM reservation r
JOIN move_request mr ON mr.id = r.move_request_id
WHERE r.id = #{reservationId,typeHandler=com.platform.reservation.UuidTypeHandler}
  AND mr.customer_id = #{customerId,typeHandler=com.platform.reservation.UuidTypeHandler}

SELECT EXISTS (
    SELECT 1 FROM technician_assignment
    WHERE reservation_id = #{reservationId,typeHandler=com.platform.reservation.UuidTypeHandler}
      AND status IN ('WORK_STARTED', 'WORK_COMPLETED')
)

SELECT EXISTS (
    SELECT 1 FROM technician_assignment
    WHERE reservation_id = #{reservationId,typeHandler=com.platform.reservation.UuidTypeHandler}
      AND status IN ('ACCEPTED', 'ON_THE_WAY', 'WORK_STARTED', 'WORK_COMPLETED')
)
